/*
 * Assemble descriptor, population-merit, glass-tolerance and basin-merit portions of adaptive traces.
 * emit_trace shares the current fitness/archive state and the previous trace population merit baseline.
 * Preserve aggregation order and the point where trace-to-trace comparison state is updated.
 */
// Generated by split_adaptive_diagnostics.py; complete trace field methods.
#include "adaptive_session.hpp"

namespace optiland { namespace optimizer_detail {


void AdaptiveSession::assemble_trace_descriptors(HybridTraceEvent& trace) {
        {
            std::vector<std::string> descriptor_keys;
            std::size_t max_axis_count = 0;
            for (const BasinElite& basin : run_.basins) {
                std::string key = basin.descriptor_key.empty()
                                      ? basin.fitness.descriptor_key
                                      : basin.descriptor_key;
                if (key.empty()) {
                    key = "__unknown__";
                }
                if (std::find(descriptor_keys.begin(), descriptor_keys.end(), key) ==
                    descriptor_keys.end()) {
                    descriptor_keys.push_back(std::move(key));
                }
                const auto& values = basin.descriptor_axis_values.empty()
                                         ? basin.fitness.descriptor_axis_values
                                         : basin.descriptor_axis_values;
                max_axis_count = std::max(max_axis_count, values.size());
            }
            trace.basin_descriptor_count = static_cast<int>(descriptor_keys.size());
            trace.basin_descriptor_axis_count = static_cast<int>(max_axis_count);
            if (max_axis_count > 0) {
                std::vector<std::vector<std::uint64_t>> unique_values(max_axis_count);
                for (const BasinElite& basin : run_.basins) {
                    const auto& values = basin.descriptor_axis_values.empty()
                                             ? basin.fitness.descriptor_axis_values
                                             : basin.descriptor_axis_values;
                    for (std::size_t axis = 0; axis < values.size(); ++axis) {
                        auto& unique_axis_values = unique_values[axis];
                        if (std::find(
                                unique_axis_values.begin(),
                                unique_axis_values.end(),
                                values[axis]) == unique_axis_values.end()) {
                            unique_axis_values.push_back(values[axis]);
                        }
                    }
                }
                int min_unique = std::numeric_limits<int>::max();
                int max_unique = 0;
                int axis_with_samples = 0;
                double sum_unique = 0.0;
                for (const auto& axis_values : unique_values) {
                    if (axis_values.empty()) {
                        continue;
                    }
                    const int unique_count = static_cast<int>(axis_values.size());
                    min_unique = std::min(min_unique, unique_count);
                    max_unique = std::max(max_unique, unique_count);
                    sum_unique += static_cast<double>(unique_count);
                    ++axis_with_samples;
                }
                if (axis_with_samples > 0) {
                    trace.basin_descriptor_axis_unique_min = min_unique;
                    trace.basin_descriptor_axis_unique_max = max_unique;
                    trace.basin_descriptor_axis_unique_mean =
                        sum_unique / static_cast<double>(axis_with_samples);
                }
            }
        }
}

void AdaptiveSession::assemble_trace_population_merits(HybridTraceEvent& trace, int epoch, const int& feasible_count, const int& trace_feasible_count, const int& constraint_feasible_count, const int& first_order_feasible_count) {
        trace.feasible_count = feasible_count;
        trace.trace_feasible_count = trace_feasible_count;
        trace.constraint_feasible_count = constraint_feasible_count;
        trace.first_order_feasible_count = first_order_feasible_count;
        const int elite_count = std::clamp(
            std::max({1,
                      run_.requested_polish_count,
                      options.parent_count,
                      options.refresh_generation.parent_count}),
            1,
            std::max(1, run_.pop_size));
        std::vector<double> population_elite_merits;
        population_elite_merits.reserve(static_cast<std::size_t>(elite_count));
        const auto population_order = sorted_fitness_indices(run_.fitness, options);
        if (!population_order.empty()) {
            const int population_best_index = population_order.front();
            if (population_best_index >= 0 && population_best_index < run_.pop_size) {
                trace.population_best_score =
                    run_.fitness[static_cast<std::size_t>(population_best_index)].score;
                trace.population_best_values = scaled_to_physical(
                    owner.variables_,
                    population_row(run_.population, population_best_index, run_.dim),
                    run_.internal_mode);
                if (options.track_population_diversity) {
                    double distance_sum = 0.0;
                    int distance_count = 0;
                    for (int row = 0; row < run_.pop_size; ++row) {
                        double squared = 0.0;
                        for (int j = 0; j < run_.dim; ++j) {
                            const double delta =
                                run_.population[static_cast<std::size_t>(row) * run_.dim +
                                           static_cast<std::size_t>(j)] -
                                run_.population[static_cast<std::size_t>(population_best_index) * run_.dim +
                                           static_cast<std::size_t>(j)];
                            squared += delta * delta;
                        }
                        if (std::isfinite(squared)) {
                            distance_sum += std::sqrt(std::max(0.0, squared));
                            ++distance_count;
                        }
                    }
                    trace.population_diversity_tracked = true;
                    trace.population_distance_to_best_count = distance_count;
                    if (distance_count > 0) {
                        trace.population_mean_euclidean_distance_to_best =
                            distance_sum / static_cast<double>(distance_count);
                    }
                }
            }
        }
        const double current_population_best_merit =
            trace.population_best_score.merit;
        trace.population_best_previous_merit = run_.last_trace_population_best_merit;
        if (std::isfinite(run_.last_trace_population_best_merit) &&
            std::isfinite(current_population_best_merit)) {
            trace.population_best_improvement =
                run_.last_trace_population_best_merit - current_population_best_merit;
            trace.population_best_improved =
                trace.population_best_improvement > 1.0e-12;
        }
        if (std::isfinite(current_population_best_merit) &&
            std::isfinite(run_.best_fitness.score.merit)) {
            trace.population_best_vs_incumbent_merit_delta =
                current_population_best_merit - run_.best_fitness.score.merit;
        }
        if (std::isfinite(current_population_best_merit)) {
            run_.last_trace_population_best_merit = current_population_best_merit;
        }
        for (int index : population_order) {
            if (static_cast<int>(population_elite_merits.size()) >= elite_count) {
                break;
            }
            population_elite_merits.push_back(
                run_.fitness[static_cast<std::size_t>(index)].score.merit);
        }
        const MeritStats population_stats = this->merit_stats(std::move(population_elite_merits));
        this->sync_adaptive_glass_tolerance_trigger_state(epoch);
        trace.population_elite_count = population_stats.count;
        trace.population_elite_mean_merit = population_stats.mean;
        trace.population_elite_median_merit = population_stats.median;
        trace.population_elite_worst_merit = population_stats.worst;
}

void AdaptiveSession::assemble_trace_glass_tolerance(HybridTraceEvent& trace) {
        trace.adaptive_glass_tolerance_enabled =
            run_.adaptive_glass_tolerance.enabled;
        trace.adaptive_glass_tolerance_updated =
            run_.adaptive_glass_tolerance.updated;
        trace.adaptive_glass_tolerance_ready =
            this->adaptive_glass_tolerance_ready();
        trace.adaptive_glass_tolerance_trigger_ready =
            run_.adaptive_glass_tolerance.trigger_ready;
        trace.adaptive_glass_tolerance_bridge_active =
            run_.adaptive_glass_tolerance.bridge_active;
        trace.adaptive_glass_tolerance_focus_frozen =
            run_.adaptive_glass_tolerance.focus_frozen;
        trace.adaptive_glass_tolerance_stop_when_ready =
            run_.adaptive_glass_tolerance.stop_when_ready;
        trace.adaptive_glass_tolerance_trigger_mode =
            run_.adaptive_glass_tolerance.trigger_mode;
        trace.adaptive_glass_tolerance_focus_clear_count =
            run_.adaptive_glass_tolerance.focus_clear_count;
        trace.adaptive_glass_tolerance_focus_clear_target =
            run_.adaptive_glass_tolerance.focus_clear_target;
        trace.adaptive_glass_tolerance_sample_count =
            run_.adaptive_glass_tolerance.sample_count;
        trace.adaptive_glass_tolerance_elite_count =
            run_.adaptive_glass_tolerance.elite_count;
        trace.adaptive_glass_tolerance_previous =
            run_.adaptive_glass_tolerance.previous;
        trace.adaptive_glass_tolerance_current =
            run_.adaptive_glass_tolerance.current;
        trace.adaptive_glass_tolerance_target =
            run_.adaptive_glass_tolerance.target;
        trace.adaptive_glass_tolerance_metric =
            run_.adaptive_glass_tolerance.metric;
}

void AdaptiveSession::assemble_trace_basin_merits(HybridTraceEvent& trace) {
        std::vector<int> basin_order(run_.basins.size());
        std::iota(basin_order.begin(), basin_order.end(), 0);
        std::stable_sort(basin_order.begin(), basin_order.end(), [this](int a, int b) {
            return candidate_better(
                run_.basins[static_cast<std::size_t>(a)].fitness,
                run_.basins[static_cast<std::size_t>(b)].fitness,
                options);
        });
        std::vector<double> basin_merits;
        basin_merits.reserve(run_.basins.size());
        std::vector<double> unique_topology_merits;
        std::vector<std::string> seen_topologies;
        for (int index : basin_order) {
            const BasinElite& basin = run_.basins[static_cast<std::size_t>(index)];
            basin_merits.push_back(basin.fitness.score.merit);
            std::string key = this->basin_key(basin);
            if (key.empty()) {
                key = "__unknown__";
            }
            if (std::find(seen_topologies.begin(), seen_topologies.end(), key) ==
                seen_topologies.end()) {
                seen_topologies.push_back(std::move(key));
                unique_topology_merits.push_back(basin.fitness.score.merit);
            }
        }
        const MeritStats basin_stats = this->merit_stats(std::move(basin_merits));
        trace.basin_elite_count = basin_stats.count;
        trace.basin_elite_mean_merit = basin_stats.mean;
        trace.basin_elite_median_merit = basin_stats.median;
        trace.basin_elite_worst_merit = basin_stats.worst;
        const MeritStats unique_topology_stats =
            this->merit_stats(std::move(unique_topology_merits));
        trace.basin_unique_topology_elite_count = unique_topology_stats.count;
        trace.basin_unique_topology_elite_mean_merit = unique_topology_stats.mean;
        trace.basin_unique_topology_elite_median_merit = unique_topology_stats.median;
        trace.basin_unique_topology_elite_worst_merit = unique_topology_stats.worst;
}


} } // namespace optiland::optimizer_detail
